  "2019 P1 Q2": {"skill":"The discriminant: equal roots.","method":"3 marks","moves":["Write the discriminant \\(b^2 - 4ac\\) with \\(a = 1\\), \\(b = k - 5\\) and \\(c = 1\\).","Equal roots means the discriminant is \\(0\\): write that and simplify.","Solve for \\(k\\)."],"marks":[1,1,1],"shows":["\\((k - 5)^2 - 4 \\times 1 \\times 1\\)","\\(k^2 - 10k + 21 = 0\\) or \\((k - 5)^2 = 4\\)",null]},
  "2019 P1 Q3": {"skill":"A circle with the same radius and a new centre.","method":"2 marks","moves":["Find the radius of \\(C_1\\) with \\(r = \\sqrt{g^2 + f^2 - c}\\).","Write the equation of \\(C_2\\) with centre \\((4, -2)\\) and that radius."],"marks":[1,1],"shows":["\\(6\\)",null]},
