  "2022 P1 Q8": {"skill":"A log equation leading to a quadratic.","method":"4 marks","moves":["Combine the left side into one log: \\(\\log_6 x(x + 5)\\).","Rewrite in exponential form: \\(x(x + 5) = 6^2\\).","Expand into a quadratic equal to \\(0\\), solve, and keep only the answer with \\(x > 0\\)."],"marks":[1,1,2],"shows":["\\(\\log_6(x(x + 5)) = \\ldots\\)","\\(x(x + 5) = 6^2\\)","\\(x^2 + 5x - 36 = 0\\)"]},
